SELECT /* SQL_ID: ModelPropertyMapper.selectTypeModelPropertyList */ (ROW_NUMBER() OVER(ORDER BY modelPrpty.model_prpty_del_yn, modelPrpty.model_prpty_sort_odrg)) AS rownum ,modelPrpty.model_prpty_id ,model.model_id ,model.model_nm ,modelprpty.prpty_id ,prpty.prpty_nm ,prpty.prpty_logic_nm ,prpty.prpty_data_sttus_mtcd ,prptyDefine.domn_model_id ,domnModel.model_nm AS domnModelNm ,prptyDefine.range_model_id ,rangeModel.model_nm AS rangeModelNm ,rangeModel.model_data_sttus_mtcd AS rangeModelDataSttusMtcd ,rangeModel.model_type_mtcd AS range_model_type_mtcd ,modelPrpty.model_prpty_sort_odrg ,modelprpty.model_prpty_val_exam ,modelprpty.std_model_id ,stdModel.model_nm AS std_model_nm ,modelprpty.model_prpty_mand_mtcd ,code.mtcd_nm as modelPrptyMandMtcdNm ,modelprpty.tbl_coln_mappg_nm ,prpty.data_array_yn ,prpty.cnt_prpty_yn ,prpty.cnt_model_id ,modelprpty.model_prpty_del_yn ,modelprpty.model_prpty_delr_id ,modelprpty.model_prpty_delr_nm ,to_char(modelprpty.model_prpty_del_dt,#{sqlDateFormat}) as modelPrptyDelDt ,modelprpty.model_prpty_del_why ,CASE WHEN c2.mtcd IS NOT NULL THEN 'Y' ELSE 'N' END AS setUsgPrptyYn ,rangeModel.data_type_mtcd AS range_data_type_mtcd FROM dtmeta.tb_meta_modelproperty modelPrpty INNER JOIN dtmeta.tb_meta_model model ON modelPrpty.model_id = model.model_id INNER JOIN dtmeta.tb_meta_property prpty ON prpty.prpty_id = modelPrpty .prpty_id INNER JOIN dtmeta.tb_meta_propertydefine prptyDefine ON prpty .prpty_id = prptyDefine.prpty_id AND prptyDefine.prpty_def_chg_yn = 'N' INNER JOIN dtmeta.tb_meta_model rangeModel ON prptyDefine.range_model_id = rangeModel.model_id INNER JOIN dtmeta.tb_meta_model domnModel ON prptyDefine.domn_model_id = domnModel.model_id LEFT JOIN dtmeta.tb_portal_code code ON modelPrpty .model_prpty_mand_mtcd = code.mtcd and code.mtcd_grp_id = 'MCG00004' LEFT JOIN dtmeta.tb_portal_code c2 ON rangeModel.data_type_mtcd = c2.mtcd AND c2.mtcd_grp_id = 'MCG00013' LEFT JOIN dtmeta.tb_meta_model stdModel on modelPrpty.std_model_id = stdModel.model_id WHERE model.model_id = #{modelId}
AND (UPPER(prpty.prpty_nm) LIKE UPPER('%'||#{searchName}||'%') OR UPPER(prpty.prpty_logic_nm) LIKE UPPER('%'||#{searchName}||'%'))
AND prpty.prpty_data_sttus_mtcd = #{prptyDataSttusMtcd}
AND modelPrpty.model_prpty_del_yn = #{modelPrptyDelYn}

SELECT /* SQL_ID: ModelPropertyMapper.selectModelPropertyCheck */
	COUNT(modelPrpty.model_prpty_id) AS cnt
FROM dtmeta.tb_meta_modelproperty modelPrpty

WHERE modelPrpty.model_prpty_del_yn='N'

AND modelPrpty.model_id = #{modelId}


AND modelPrpty.prpty_id = #{prptyId}

mapper.insert:

SELECT CONCAT('MP', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_common') AS varchar), 4, '0'))	

INSERT /* SQL_ID: ModelPropertyMapper.insertModelProperty */
  INTO dtmeta.tb_meta_modelproperty
	 ( 
	   model_prpty_id
	 , model_id
	 , prpty_id 
	 , model_prpty_mand_mtcd 
	 , model_prpty_val_exam
	 , std_model_id
	 , model_prpty_sort_odrg
	 , model_prpty_del_yn 
	 , model_prpty_regr_id 
	 , model_prpty_regr_nm 
	 , model_prpty_reg_dt 
	 , model_prpty_amdr_id 
	 , model_prpty_amdr_nm 
	 , model_prpty_amd_dt 
	 ) 
VALUES 
	 ( 
       #{modelPrptyId}    
	 , #{modelId}   
	 , #{prptyId}
	 , #{modelPrptyMandMtcd}
	 , #{modelPrptyValExam}
	 , #{stdModelId}
	 , ( SELECT COALESCE(MAX(model_prpty_sort_odrg), 0) + 1  FROM dtmeta.tb_meta_modelproperty  WHERE model_id = #{modelId} AND model_prpty_del_yn = 'N' )
	 , 'N'
	 , #{modelPrptyRegrId}
	 , #{modelPrptyRegrNm} 
	 , current_timestamp
	 , #{modelPrptyAmdrId}
	 , #{modelPrptyAmdrNm}
	 , current_timestamp
	 )

mapper.update:
		UPDATE /* SQL_ID: ModelPropertyMapper.updateModelProperty*/
               dtmeta.tb_meta_modelproperty
		   SET model_prpty_val_exam         = #{modelPrptyValExam}
		     , std_model_id                 = #{stdModelId}
		     , model_prpty_mand_mtcd        = #{modelPrptyMandMtcd}
		     , model_prpty_sort_odrg		= #{modelPrptySortOdrg}::int
		     , model_prpty_amdr_id			= #{modelPrptyAmdrId}
		     , model_prpty_amdr_nm			= #{modelPrptyAmdrNm}
		     , model_prpty_amd_dt			= current_timestamp

			 , tbl_coln_mappg_nm			= #{tblColnMappgNm}

		 WHERE model_prpty_id		        = #{modelPrptyId}
		 AND   model_id						= #{modelId}

		UPDATE /* SQL_ID: ModelPropertyMapper.updateModelPropertyDelYn*/
               dtmeta.tb_meta_modelproperty
		   SET model_prpty_del_yn           = 'Y'
		     , model_prpty_del_dt           = current_timestamp
		     , model_prpty_del_why		    = #{modelPrptyDelWhy}
		     , model_prpty_delr_nm		    = #{modelPrptyDelrNm}
		 	 , model_prpty_amdr_id			= #{modelPrptyAmdrId}
		     , model_prpty_amdr_nm			= #{modelPrptyAmdrNm}
		     , model_prpty_amd_dt			= current_timestamp    
		 WHERE model_prpty_id		        = #{modelPrptyId}

mapper.delete:
DELETE /* SQL_ID: ModelPropertyMapper.deleteModelProperty*/
FROM dtmeta.tb_meta_modelproperty
where model_prpty_id = #{modelPrptyId}

