SELECT /* SQL_ID: ModelPropertyMapper.selectModelPropertyInfoListByModelId */ t1.model_prpty_id , t1.model_id , t1.prpty_id , t1.model_prpty_mand_mtcd , c1.mtcd_nm AS model_prpty_mand_mtcd_nm , t1.model_prpty_sort_odrg , t1.model_prpty_val_exam , t1.tbl_coln_mappg_nm , t1.std_model_id , t1.model_prpty_del_yn , t2.prpty_nm , t2.prpty_logic_nm , t2.data_array_yn , t2.prpty_scrn_indc_yn , t2.cnt_prpty_yn , t2.cnt_model_id , t9.model_nm AS cnt_model_nm , t3.domn_model_id , t3.range_model_id , COALESCE(t3.range_mtcd_grp_id, t5.mtcd_grp_id) AS range_mtcd_grp_id , t3.prpty_def_chg_yn , t4.model_nm AS domn_model_nm , t4.model_logic_nm AS domn_model_logic_nm , t5.model_nm AS range_model_nm , t5.model_logic_nm AS range_model_logic_nm , t5.model_type_mtcd AS range_model_type_mtcd , t5.type_model_id AS range_type_model_id , t7.model_nm AS range_type_model_nm , t5.data_type_mtcd AS range_data_type_mtcd , t5.use_lang_mtcd AS range_use_lang_mtcd , t6.prpty_nm AS range_ref_prpty_nm , CASE WHEN c2.mtcd IS NOT NULL THEN 'Y' ELSE 'N' END AS set_usg_prpty_yn , t8.model_nm AS std_model_nm FROM dtmeta.tb_meta_modelproperty t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_propertydefine t3 ON t1.prpty_id = t3.prpty_id AND t3.prpty_def_chg_yn = 'N' LEFT OUTER JOIN dtmeta.tb_meta_model t4 ON t3.domn_model_id = t4.model_id AND t4.model_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_meta_model t5 ON t3.range_model_id = t5.model_id AND t5.model_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_meta_property t6 ON t3.ref_prpty_id = t6.prpty_id AND t6.prpty_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_portal_code c1 ON t1.model_prpty_mand_mtcd = c1.mtcd AND c1.mtcd_grp_id = 'MCG00004' LEFT OUTER JOIN dtmeta.tb_portal_code c2 ON t5.data_type_mtcd = c2.mtcd AND c2.mtcd_grp_id = 'MCG00013' LEFT OUTER JOIN dtmeta.tb_meta_model t7 ON t5.type_model_id = t7.model_id LEFT OUTER JOIN dtmeta.tb_meta_model t8 ON t1.std_model_id = t8.model_id LEFT OUTER JOIN dtmeta.tb_meta_model t9 ON t2.cnt_model_id = t9.model_id WHERE t1.model_prpty_del_yn = 'N' AND t1.model_id = #{modelId}
AND t5.model_type_mtcd = #{modelTypeMtcd}
ORDER BY t1.model_prpty_sort_odrg, t2.prpty_sort_odrg

SELECT /* SQL_ID: ModelPropertyMapper.selectModelPropertyInfoListByModelIdForNeo4j */ t1.model_prpty_id , t1.model_id , t1.prpty_id , t1.model_prpty_mand_mtcd , c1.mtcd_nm AS model_prpty_mand_mtcd_nm , t1.model_prpty_sort_odrg , t1.model_prpty_val_exam , t1.tbl_coln_mappg_nm , t1.std_model_id , t1.model_prpty_del_yn , t2.prpty_nm , t2.prpty_logic_nm , t2.data_array_yn , t2.prpty_scrn_indc_yn , t2.cnt_prpty_yn , t2.cnt_model_id , t9.model_nm AS cnt_model_nm , t3.domn_model_id , t3.range_model_id , COALESCE(t3.range_mtcd_grp_id, t5.mtcd_grp_id) AS range_mtcd_grp_id , t3.prpty_def_chg_yn , t4.model_nm AS domn_model_nm , t4.model_logic_nm AS domn_model_logic_nm , t5.model_nm AS range_model_nm , t5.model_logic_nm AS range_model_logic_nm , t5.model_type_mtcd AS range_model_type_mtcd , t5.type_model_id AS range_type_model_id , t7.model_nm AS range_type_model_nm , t5.data_type_mtcd AS range_data_type_mtcd , t5.use_lang_mtcd AS range_use_lang_mtcd , t6.prpty_nm AS range_ref_prpty_nm , CASE WHEN c2.mtcd IS NOT NULL THEN 'Y' ELSE 'N' END AS set_usg_prpty_yn , t8.model_nm AS std_model_nm FROM dtmeta.tb_meta_modelproperty t1 INNER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' INNER JOIN dtmeta.tb_meta_propertydefine t3 ON t1.prpty_id = t3.prpty_id AND t3.prpty_def_chg_yn = 'N' LEFT OUTER JOIN dtmeta.tb_meta_model t4 ON t3.domn_model_id = t4.model_id AND t4.model_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_meta_model t5 ON t3.range_model_id = t5.model_id AND t5.model_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_meta_property t6 ON t3.ref_prpty_id = t6.prpty_id AND t6.prpty_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_portal_code c1 ON t1.model_prpty_mand_mtcd = c1.mtcd AND c1.mtcd_grp_id = 'MCG00004' LEFT OUTER JOIN dtmeta.tb_portal_code c2 ON t5.data_type_mtcd = c2.mtcd AND c2.mtcd_grp_id = 'MCG00013' LEFT OUTER JOIN dtmeta.tb_meta_model t7 ON t5.type_model_id = t7.model_id LEFT OUTER JOIN dtmeta.tb_meta_model t8 ON t1.std_model_id = t8.model_id LEFT OUTER JOIN dtmeta.tb_meta_model t9 ON t2.cnt_model_id = t9.model_id WHERE t1.model_prpty_del_yn = 'N' AND t1.model_id = #{modelId}
AND t5.model_type_mtcd = #{modelTypeMtcd}
AND t2.data_array_yn = #{dataArrayYn}
ORDER BY t1.model_prpty_sort_odrg, t2.prpty_sort_odrg
